1	// pattern: Mixed (Functional Core types + Imperative Shell commands)
2	//
3	// Permanent identity removal: the wallet-side counterpart to the PDS's
4	// `requestAccountDelete`/`deleteAccount` endpoints plus a did:plc tombstone.
5	//
6	// A removal has three network/local effects, applied in a strict order:
7	//   1. deleteAccount   — the PDS purges all account data and emits an `#account`
8	//                        (`status="deleted"`) firehose frame relays consume.
9	//   2. plc_tombstone   — the wallet signs a tombstone with the DID's device key
10	//                        (rotationKeys[0]) and POSTs it to plc.directory, so the
11	//                        did:plc itself is retired network-wide (the PDS cannot do
12	//                        this — it never holds the rotation key, ADR-0001).
13	//   3. local wipe      — `IdentityStore::remove_identity` deletes every per-DID
14	//                        Keychain entry.
15	//
16	// Ordering invariant: the local wipe runs LAST and only after the tombstone
17	// submits, because the wipe deletes the device key that signs the tombstone. If the
18	// tombstone submit fails, the account is already deleted (its single-use email token
19	// spent) but the device key survives — the UI resumes via `tombstone_identity`, which
20	// retries only the tombstone + wipe.
21	
22	use serde::Serialize;
23	
24	use crate::identity_store::{IdentityStore, PerDidSignError};
25	use crate::pds_client::{PdsClient, PdsClientError};
26	use crate::session_provider::{SessionError, SessionProvider, UnlockReason};
27	
28	/// Keychain account holding the durable "removal in progress (post-delete)" index:
29	/// a JSON array of DIDs whose PDS account was deleted but whose tombstone + local
30	/// wipe has not yet completed. This is the recovery marker that makes a removal
31	/// interrupted after `deleteAccount` (e.g. iOS killing the app mid-tombstone)
32	/// resumable — on launch the UI reconciles any listed DID straight to the
33	/// tombstone-only retry rather than the full request flow (which would fail against
34	/// the already-deleted account).
35	const PENDING_REMOVALS_ACCOUNT: &str = "pending-removals";
36	
37	/// Load the set of DIDs with a pending post-delete removal, propagating a genuine
38	/// Keychain read failure.
39	///
40	/// A missing entry is an empty set, and corrupt JSON reads as empty (the marker is a
41	/// best-effort payload — a decode failure must not wedge the flow). But a real
42	/// Keychain security/IO error is returned, NOT swallowed: the mutators
43	/// (`mark_removal_pending` / `clear_removal_pending`) do a read-modify-write, so
44	/// silently treating a transient read failure as "empty" would let the subsequent
45	/// save overwrite the Keychain and drop any *other* DIDs' pending markers.
46	fn load_pending_removals_strict() -> Result<Vec<String>, crate::keychain::KeychainError> {
47	    match crate::keychain::get_item(PENDING_REMOVALS_ACCOUNT) {
48	        Ok(bytes) => Ok(serde_json::from_slice::<Vec<String>>(&bytes).unwrap_or_else(|e| {
49	            tracing::warn!(error = %e, "pending-removals Keychain entry is not valid JSON; treating as empty");
50	            Vec::new()
51	        })),
52	        Err(e) if crate::keychain::is_not_found(&e) => Ok(Vec::new()),
53	        Err(e) => Err(e),
54	    }
55	}
56	
57	/// Best-effort read of the pending-removal set for the infallible launch check.
58	///
59	/// Any Keychain trouble reads as an empty set — `list_pending_removals` is called
60	/// unconditionally on every launch and must never surface an error that could block it.
61	/// Read-modify-write callers must use [`load_pending_removals_strict`] instead, so a
62	/// transient read failure cannot clobber unrelated markers.
63	fn load_pending_removals() -> Vec<String> {
64	    load_pending_removals_strict().unwrap_or_else(|e| {
65	        tracing::warn!(error = %e, "Keychain error loading pending-removals; treating as empty");
66	        Vec::new()
67	    })
68	}
69	
70	/// Persist the pending-removals set. An empty set deletes the entry entirely so the
71	/// Keychain never carries a stale `[]`.
72	fn save_pending_removals(dids: &[String]) -> Result<(), crate::keychain::KeychainError> {
73	    if dids.is_empty() {
74	        return match crate::keychain::delete_item(PENDING_REMOVALS_ACCOUNT) {
75	            Ok(()) => Ok(()),
76	            Err(e) if crate::keychain::is_not_found(&e) => Ok(()),
77	            Err(e) => Err(e),
78	        };
79	    }
80	    // Vec<String> → JSON is infallible; unwrap keeps the signature Keychain-only.
81	    let json = serde_json::to_vec(dids).expect("Vec<String> always serializes to JSON");
82	    crate::keychain::store_item(PENDING_REMOVALS_ACCOUNT, &json)
83	}
84	
85	/// Mark `did` as having a pending post-delete removal (idempotent).
86	///
87	/// Called the instant `deleteAccount` succeeds, before the tombstone network round
88	/// trip — the step iOS is most likely to interrupt by backgrounding the app.
89	fn mark_removal_pending(did: &str) -> Result<(), crate::keychain::KeychainError> {
90	    let mut dids = load_pending_removals_strict()?;
91	    if !dids.iter().any(|d| d == did) {
92	        dids.push(did.to_string());
93	        save_pending_removals(&dids)?;
94	    }
95	    Ok(())
96	}
97	
98	/// Clear `did`'s pending-removal marker once the tombstone + wipe have completed.
99	fn clear_removal_pending(did: &str) -> Result<(), crate::keychain::KeychainError> {
100	    let mut dids = load_pending_removals_strict()?;
101	    let before = dids.len();
102	    dids.retain(|d| d != did);
103	    if dids.len() != before {
104	        save_pending_removals(&dids)?;
105	    }
106	    Ok(())
107	}
108	
109	/// Best-effort clear of the pending-removal marker after a successful removal.
110	///
111	/// A failure here is non-fatal: the removal already succeeded, and a lingering marker
112	/// only re-offers the (now idempotent, wipe-only) tombstone retry on the next launch,
113	/// which clears it. Never fail the removal over marker cleanup.
114	fn clear_removal_pending_best_effort(did: &str) {
115	    if let Err(e) = clear_removal_pending(did) {
116	        tracing::warn!(did = did, error = %e, "failed to clear pending-removal marker after removal");
117	    }
118	}
