120	/// Errors from the identity-removal flow.
121	///
122	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE", ... }` to match the other wallet
123	/// error enums (`RecoveryError`, `SessionError`, …). Variants are ordered by the step
124	/// that produces them so the UI can tell what already happened — notably, a
125	/// `PlcDirectoryError`/`RateLimited`/`NetworkError` *after* `InvalidToken` succeeded
126	/// means the PDS account is gone and only the tombstone + wipe remain (resume via
127	/// `tombstone_identity`).
128	#[derive(Debug, Serialize, thiserror::Error)]
129	#[serde(
130	    tag = "code",
131	    rename_all = "SCREAMING_SNAKE_CASE",
132	    rename_all_fields = "camelCase"
133	)]
134	pub enum RemovalError {
135	    /// The identity has no usable session; the UI must run the passwordless
136	    /// `sovereignLogin(did)` unlock before requesting deletion.
137	    #[error("identity needs a passwordless unlock before removal")]
138	    SessionRequired { reason: UnlockReason },
139	    /// `requestAccountDelete` failed (could not mint/send the confirmation code).
140	    #[error("failed to request account deletion: {message}")]
141	    RequestDeleteFailed { message: String },
142	    /// The PDS rejected the account password or the emailed confirmation code.
143	    #[error("invalid password or confirmation code")]
144	    InvalidToken,
145	    /// `deleteAccount` failed for a reason other than bad credentials.
146	    #[error("account deletion failed: {message}")]
147	    AccountDeleteFailed { message: String },
148	    /// The DID's plc.directory audit log could not be fetched/parsed for the tombstone `prev`.
149	    #[error("could not read the identity's PLC log: {message}")]
150	    InvalidAuditLog { message: String },
151	    /// Building or signing the tombstone with the device key failed.
152	    #[error("failed to sign the tombstone: {message}")]
153	    TombstoneSigningFailed { message: String },
154	    /// plc.directory rejected the tombstone. The account is already deleted — retry via
155	    /// `tombstone_identity`.
156	    #[error("plc.directory rejected the tombstone: {message}")]
157	    PlcDirectoryError { message: String },
158	    /// The DID's device key / managed-dids entry is missing.
159	    #[error("identity not found: {message}")]
160	    IdentityNotFound { message: String },
161	    /// The account was deleted and tombstoned, but the local Keychain wipe failed.
162	    #[error("local cleanup failed after removal: {message}")]
163	    LocalWipeFailed { message: String },
164	    /// A server rate-limited a step; the UI can retry after `retryAfter`.
165	    #[error("rate limited")]
166	    RateLimited { retry_after: Option<String> },
167	    /// Transport failure reaching the PDS or plc.directory.
168	    #[error("network error: {message}")]
169	    NetworkError { message: String },
170	}
171	
172	/// The successful result of a removal (or a `tombstone_identity` resume).
173	#[derive(Debug, Serialize, Clone, PartialEq, Eq)]
174	#[serde(rename_all = "camelCase")]
175	pub struct RemovalOutcome {
176	    /// The CID of the submitted did:plc tombstone operation.
177	    pub tombstone_cid: String,
178	    /// `true` if the removed DID was the last managed identity — the UI returns to
179	    /// onboarding rather than the identity list.
180	    pub was_last_identity: bool,
181	}
182	
183	/// Map a `deleteAccount` `PdsClientError` onto the removal error surface.
184	///
185	/// A 401 (wrong password) and a 400 `INVALID_TOKEN` (bad/expired confirmation code)
186	/// both collapse to `InvalidToken` — the UI re-prompts for both — while other XRPC
187	/// failures are a distinct `AccountDeleteFailed`.
188	fn map_delete_account_error(e: PdsClientError) -> RemovalError {
189	    match e {
190	        PdsClientError::Unauthorized { .. } => RemovalError::InvalidToken,
191	        PdsClientError::XrpcError { status: 400, .. } => RemovalError::InvalidToken,
192	        PdsClientError::RateLimited { retry_after, .. } => {
193	            RemovalError::RateLimited { retry_after }
194	        }
195	        PdsClientError::NetworkError { message } => RemovalError::NetworkError { message },
196	        other => RemovalError::AccountDeleteFailed {
197	            message: other.to_string(),
198	        },
199	    }
200	}
201	
202	/// Map a `requestAccountDelete` `PdsClientError` onto the removal error surface.
203	fn map_request_delete_error(e: PdsClientError) -> RemovalError {
204	    match e {
205	        PdsClientError::RateLimited { retry_after, .. } => {
206	            RemovalError::RateLimited { retry_after }
207	        }
208	        PdsClientError::NetworkError { message } => RemovalError::NetworkError { message },
209	        other => RemovalError::RequestDeleteFailed {
210	            message: other.to_string(),
211	        },
212	    }
213	}
214	
215	/// Map a `SessionProvider` failure onto the removal error surface.
216	fn map_session_error(e: SessionError) -> RemovalError {
217	    match e {
218	        SessionError::NeedsUnlock { reason } => RemovalError::SessionRequired { reason },
219	        SessionError::IdentityNotFound => RemovalError::IdentityNotFound {
220	            message: "no managed identity for this DID".to_string(),
221	        },
222	        SessionError::RateLimited { retry_after } => RemovalError::RateLimited { retry_after },
223	        SessionError::Offline { message } => RemovalError::NetworkError { message },
224	        other => RemovalError::RequestDeleteFailed {
225	            message: other.to_string(),
226	        },
227	    }
228	}
