230	/// Submit the tombstone, then — only if that succeeded — run the local wipe.
231	///
232	/// Split out so the ordering invariant ("the wipe never runs on a submit failure",
233	/// which keeps the device key alive for a `tombstone_identity` retry) is unit-testable
234	/// without a Keychain or a live plc.directory.
235	async fn submit_then_wipe<Submit, Wipe>(submit: Submit, wipe: Wipe) -> Result<(), RemovalError>
236	where
237	    Submit: std::future::Future<Output = Result<(), RemovalError>>,
238	    Wipe: FnOnce() -> Result<(), RemovalError>,
239	{
240	    submit.await?;
241	    wipe()
242	}
243	
244	/// Build + sign + submit the did:plc tombstone, then wipe local Keychain material.
245	///
246	/// Shared by `confirm_identity_removal` (after the PDS account is deleted) and
247	/// `tombstone_identity` (the resume path, where the account is already gone). Returns
248	/// the tombstone CID on success.
249	async fn tombstone_and_wipe(pds_client: &PdsClient, did: &str) -> Result<String, RemovalError> {
250	    let store = IdentityStore;
251	
252	    // 1. Fetch + parse the audit log and locate the head (newest non-nullified) operation.
253	    let audit_log_json =
254	        pds_client
255	            .fetch_audit_log(did)
256	            .await
257	            .map_err(|e| RemovalError::InvalidAuditLog {
258	                message: format!("failed to fetch audit log: {e}"),
259	            })?;
260	    let audit_log =
261	        crypto::parse_audit_log(&audit_log_json).map_err(|e| RemovalError::InvalidAuditLog {
262	            message: format!("failed to parse audit log: {e}"),
263	        })?;
264	    let head = audit_log
265	        .iter()
266	        .rev()
267	        .find(|e| !e.nullified)
268	        .ok_or_else(|| RemovalError::InvalidAuditLog {
269	            message: "audit log has no non-nullified operation to chain onto".to_string(),
270	        })?;
271	    let head_cid = head.cid.clone();
272	
273	    // Idempotent resume: if the DID is already tombstoned (its head IS a tombstone), the
274	    // submit already landed on plc.directory — only the local wipe remains. Submitting a
275	    // second tombstone would be rejected (a retired DID accepts no further ops), so a resume
276	    // after a wipe-only failure must skip straight to the wipe. This is what makes
277	    // `tombstone_identity` safe to call after a partial success.
278	    let head_is_tombstone =
279	        head.operation.get("type").and_then(|t| t.as_str()) == Some("plc_tombstone");
280	    if head_is_tombstone {
281	        wipe_local(&store, did)?;
282	        return Ok(head_cid);
283	    }
284	
285	    // The tombstone chains onto the head and must be signed by one of the head op's
286	    // `rotationKeys`. Verifying against those (not merely the local device key) is what
287	    // proves the wallet's key is still a *current* rotation key — the exact authorization
288	    // plc.directory will enforce — so a device key that is no longer in the rotation set
289	    // (e.g. after a migrate-away) fails fast locally instead of after the network round trip.
290	    let head_rotation_keys = extract_rotation_keys(&head.operation);
291	    if head_rotation_keys.is_empty() {
292	        return Err(RemovalError::InvalidAuditLog {
293	            message: "head operation has no rotationKeys to authorize the tombstone".to_string(),
294	        });
295	    }
296	
297	    // 2. Obtain the per-DID device-key signing closure (rotationKeys[0]).
298	    let sign = crate::identity_store::per_did_sign_closure(did).map_err(|e| match e {
299	        PerDidSignError::DeviceKeyNotFound { message } => {
300	            RemovalError::IdentityNotFound { message }
301	        }
302	        PerDidSignError::SigningSetupFailed { message } => {
303	            RemovalError::TombstoneSigningFailed { message }
304	        }
305	    })?;
306	
307	    // 3. Build + sign the tombstone (prev = the head CID).
308	    let tombstone = crypto::build_did_plc_tombstone_op(&head_cid, sign).map_err(|e| {
309	        RemovalError::TombstoneSigningFailed {
310	            message: format!("failed to build tombstone: {e}"),
311	        }
312	    })?;
313	
314	    // 3b. Local self-check against the head op's authorized rotation keys (see above).
315	    crypto::verify_plc_tombstone_op(&tombstone.signed_op_json, &head_rotation_keys).map_err(
316	        |e| RemovalError::TombstoneSigningFailed {
317	            message: format!("tombstone self-verification failed: {e}"),
318	        },
319	    )?;
320	
321	    let op_value: serde_json::Value =
322	        serde_json::from_str(&tombstone.signed_op_json).map_err(|e| {
323	            RemovalError::TombstoneSigningFailed {
324	                message: format!("failed to parse signed tombstone JSON: {e}"),
325	            }
326	        })?;
327	
328	    // 4. Submit to plc.directory, THEN (only on success) 5. wipe local material.
329	    //    Every failure in this function is post-delete (the account is already gone when
330	    //    `confirm_identity_removal` calls us), so PLC-submit transport/rate-limit failures
331	    //    fold into `PlcDirectoryError` rather than the bare `NetworkError`/`RateLimited` the
332	    //    deletion stage uses — that keeps the two stages' error codes disjoint, so the UI
333	    //    only enters the tombstone-retry path for genuinely post-delete failures.
334	    let did_owned = did.to_string();
335	    submit_then_wipe(
336	        async {
337	            pds_client
338	                .post_plc_operation(&did_owned, &op_value)
339	                .await
340	                .map_err(|e| RemovalError::PlcDirectoryError {
341	                    message: format!("plc.directory rejected the tombstone: {e}"),
342	                })
343	        },
344	        || wipe_local(&store, &did_owned),
345	    )
346	    .await?;
347	
348	    Ok(tombstone.cid)
349	}
350	
351	/// Extract a PLC operation's `rotationKeys` as typed did:key URIs (empty if absent/malformed).
352	fn extract_rotation_keys(operation: &serde_json::Value) -> Vec<crypto::DidKeyUri> {
353	    operation
354	        .get("rotationKeys")
355	        .and_then(|v| v.as_array())
356	        .map(|arr| {
357	            arr.iter()
358	                .filter_map(|v| v.as_str().map(|s| crypto::DidKeyUri(s.to_string())))
359	                .collect()
360	        })
361	        .unwrap_or_default()
362	}
363	
364	/// Wipe the DID's local Keychain material. Best-effort and idempotent: a missing
365	/// managed-dids entry (already removed by a prior partial run) is success, not failure.
366	fn wipe_local(store: &IdentityStore, did: &str) -> Result<(), RemovalError> {
367	    match store.remove_identity(did) {
368	        Ok(()) => Ok(()),
369	        Err(crate::identity_store::IdentityStoreError::IdentityNotFound) => Ok(()),
370	        Err(e) => Err(RemovalError::LocalWipeFailed {
371	            message: format!("failed to wipe local identity material: {e}"),
372	        }),
373	    }
374	}
375	
376	/// `true` if no managed identities remain — the UI returns to onboarding rather than the
377	/// identity list. Shared by the tombstone-completing paths and the local-only forget path.
378	fn no_identities_remain() -> Result<bool, RemovalError> {
379	    IdentityStore
380	        .list_identities()
381	        .map(|ids| ids.is_empty())
382	        .map_err(|e| RemovalError::LocalWipeFailed {
383	            message: format!("failed to re-read managed identities: {e}"),
384	        })
385	}
386	
387	/// Compute the `RemovalOutcome` after a successful `tombstone_and_wipe`.
388	fn removal_outcome(tombstone_cid: String) -> Result<RemovalOutcome, RemovalError> {
389	    Ok(RemovalOutcome {
390	        tombstone_cid,
391	        was_last_identity: no_identities_remain()?,
392	    })
393	}
