395	/// Tauri command: request permanent deletion — emails a single-use confirmation code.
396	///
397	/// Obtains a full-access session for `did` (the frontend runs the passwordless unlock
398	/// first if this returns `SessionRequired`) and calls `requestAccountDelete`. The PDS
399	/// emails a 1-hour code to the account address; the user then supplies that code plus
400	/// the account password to `confirm_identity_removal`.
401	#[tauri::command]
402	pub async fn request_identity_removal(
403	    state: tauri::State<'_, crate::oauth::AppState>,
404	    did: String,
405	) -> Result<(), RemovalError> {
406	    let now =
407	        crate::sovereign_session::unix_timestamp().map_err(|_| RemovalError::NetworkError {
408	            message: "system clock is unavailable".to_string(),
409	        })?;
410	    let session = SessionProvider
411	        .full_access_client(state.pds_client(), &IdentityStore, &did, now)
412	        .await
413	        .map_err(map_session_error)?;
414	
415	    crate::pds_client::request_account_delete(&session.client)
416	        .await
417	        .map_err(map_request_delete_error)
418	}
419	
420	/// Tauri command: confirm removal — delete on the PDS, tombstone the DID, wipe locally.
421	///
422	/// `password` is the account password (set during the DID ceremony); `token` is the
423	/// emailed confirmation code. `deleteAccount` is attempted FIRST, so a wrong
424	/// password/code (`InvalidToken`) leaves everything intact and the UI re-prompts. Once
425	/// the account is deleted, the tombstone + wipe run via `tombstone_and_wipe`.
426	#[tauri::command]
427	pub async fn confirm_identity_removal(
428	    state: tauri::State<'_, crate::oauth::AppState>,
429	    did: String,
430	    password: String,
431	    token: String,
432	) -> Result<RemovalOutcome, RemovalError> {
433	    // The account's PDS base URL comes from its still-present token record (the wipe is
434	    // last). Falling back to live discovery keeps a stale/absent record from stranding
435	    // an otherwise-deletable account.
436	    let pds_url = resolve_pds_url(state.pds_client(), &did).await?;
437	
438	    // 1. Permanently delete the account on the PDS (body-authed; no session needed).
439	    state
440	        .pds_client()
441	        .delete_account(&pds_url, &did, &password, &token)
442	        .await
443	        .map_err(map_delete_account_error)?;
444	
445	    // The account is now permanently gone and the single-use email code is spent — from
446	    // here on, only the tombstone + local wipe remain. Persist a durable marker BEFORE the
447	    // tombstone's network round trip so that if iOS kills/suspends the app mid-tombstone,
448	    // the next launch resumes via `tombstone_identity` rather than the request flow (which
449	    // would fail against the deleted account). A marker-write failure is logged but never
450	    // blocks the removal: the account is already deleted, so aborting here would only strand
451	    // the identity harder.
452	    if let Err(e) = mark_removal_pending(&did) {
453	        tracing::warn!(did = %did, error = %e, "failed to persist pending-removal marker after deleteAccount");
454	    }
455	
456	    // 2 + 3. Tombstone the did:plc, then wipe local material.
457	    let tombstone_cid = tombstone_and_wipe(state.pds_client(), &did).await?;
458	    clear_removal_pending_best_effort(&did);
459	    removal_outcome(tombstone_cid)
460	}
461	
462	/// Tauri command: resume a removal whose PDS account was already deleted.
463	///
464	/// Used when `confirm_identity_removal` deleted the account but the tombstone or wipe
465	/// failed: the single-use deletion token is already spent, so re-running `confirm`
466	/// would 401 at `deleteAccount`. `tombstone_and_wipe` is idempotent — if the tombstone
467	/// already landed (the DID's head is a tombstone), it does a wipe-only retry rather than
468	/// submitting a second, doomed operation; otherwise it completes the tombstone + wipe.
469	#[tauri::command]
470	pub async fn tombstone_identity(
471	    state: tauri::State<'_, crate::oauth::AppState>,
472	    did: String,
473	) -> Result<RemovalOutcome, RemovalError> {
474	    let tombstone_cid = tombstone_and_wipe(state.pds_client(), &did).await?;
475	    clear_removal_pending_best_effort(&did);
476	    removal_outcome(tombstone_cid)
477	}
