479	/// Tauri command: list DIDs with a pending post-delete removal.
480	///
481	/// Backs the launch-time reconciliation: if a removal deleted the PDS account but was
482	/// interrupted before the tombstone + wipe finished, the DID stays listed here so the UI
483	/// can resume it (idempotent `tombstone_identity`) instead of re-entering the request
484	/// flow. Infallible — any Keychain/decoding trouble reads as an empty list, so it can be
485	/// called unconditionally on every launch.
486	#[tauri::command]
487	pub fn list_pending_removals() -> Vec<String> {
488	    load_pending_removals()
489	}
