516	/// Resolve the PDS base URL for `did`: the stored token record first, then live
517	/// discovery. Used only to address the body-authed `deleteAccount` endpoint.
518	async fn resolve_pds_url(pds_client: &PdsClient, did: &str) -> Result<String, RemovalError> {
519	    if let Ok(Some(record)) = IdentityStore.load_oauth_tokens(did) {
520	        if !record.pds_url.is_empty() {
521	            return Ok(record.pds_url);
522	        }
523	    }
524	    let (pds_url, _doc) =
525	        pds_client
526	            .discover_pds(did)
527	            .await
528	            .map_err(|e| RemovalError::NetworkError {
529	                message: format!("could not resolve the identity's PDS: {e}"),
530	            })?;
531	    Ok(pds_url)
532	}
