36	  // warn → confirm (code + password) → (on partial failure) tombstone_retry.
37	  // forget_confirm is the local-only escape hatch, reachable whenever the server-side
38	  // deletion can't proceed (the account no longer exists on its PDS).
39	  type Phase =
40	    | 'warn'
41	    | 'requesting'
42	    | 'confirm'
43	    | 'working'
44	    | 'tombstone_retry'
45	    | 'forget_confirm';
46	  let phase = $state<Phase>('warn');
47	  let error = $state<string | null>(null);
48	
49	  let code = $state('');
50	  let password = $state('');
51	
52	  let canConfirm = $derived(code.trim().length > 0 && password.length > 0);
53	
54	  // If a prior attempt already deleted the PDS account but was interrupted before the
55	  // tombstone + wipe finished (the app was killed mid-flow), the account is gone and the
56	  // single-use email code is spent — the request flow would fail. Resume straight to the
57	  // tombstone-only retry instead. Checked on every mount so this self-corrects no matter
58	  // how the screen was reached (launch reconciliation or manual navigation).
59	  onMount(async () => {
60	    try {
61	      const pending = await listPendingRemovals();
62	      if (pending.includes(did) && phase === 'warn') {
63	        phase = 'tombstone_retry';
64	      }
65	    } catch (e) {
