96	  // local-only wipe into a full network retirement (sign + publish a did:plc tombstone) for an
97	  // advanced user who is certain they want to torch the identity everywhere, not just here.
98	  let showAdvanced = $state(false);
99	  let alsoTombstone = $state(false);
