113	  /** Translate a typed RemovalError (or any throwable) into a display string. */
114	  function messageFor(raw: unknown): string {
115	    if (isCodedError(raw)) {
116	      const err = raw as RemovalError;
117	      switch (err.code) {
118	        case 'SESSION_REQUIRED':
119	          return 'This identity needs to be unlocked first.';
120	        case 'REQUEST_DELETE_FAILED':
121	          return `Could not start deletion: ${err.message || 'unknown error'}`;
122	        case 'INVALID_TOKEN':
